package com.guocheng.mediapocket;
import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import javax.xml.parsers.*;import org.w3c.dom.*;import org.xml.sax.InputSource;
/** UPnP MediaRenderer discovery and AVTransport. No simulated devices or successful-playback placeholders. */
final class DlnaClient {
 static final String SERVICE="urn:schemas-upnp-org:service:AVTransport:1";
 static final class Device {final String name,udn,service;final URL control;Device(String name,String udn,String service,URL control){this.name=name;this.udn=udn;this.service=service;this.control=control;}String key(){return udn.isEmpty()?control.toString():udn;}}
 static boolean local(InetAddress address){return !address.isAnyLocalAddress()&&!address.isMulticastAddress()&&(address.isSiteLocalAddress()||address.isLinkLocalAddress()||address.isLoopbackAddress());}
 static URL localUrl(String raw)throws Exception{URL u=new URL(raw);if(!(u.getProtocol().equals("http")||u.getProtocol().equals("https"))||u.getUserInfo()!=null)throw new IOException("设备地址类型不支持");InetAddress[] addresses=InetAddress.getAllByName(u.getHost());if(addresses.length==0)throw new IOException("设备地址无法解析");for(InetAddress address:addresses)if(!local(address))throw new IOException("仅接受局域网设备地址");return u;}
 static Map<String,String> headers(String packet){LinkedHashMap<String,String> map=new LinkedHashMap<>();String[] lines=packet.split("\\r?\\n");if(lines.length==0||!lines[0].matches("(?i)^HTTP/1\\.[01] 200(?: .*)?$"))return map;for(int i=1;i<lines.length;i++){int at=lines[i].indexOf(':');if(at>0)map.put(lines[i].substring(0,at).trim().toLowerCase(Locale.ROOT),lines[i].substring(at+1).trim());}return map;}
 static Document xml(String raw)throws Exception{if(raw.toUpperCase(Locale.ROOT).contains("<!DOCTYPE")||raw.toUpperCase(Locale.ROOT).contains("<!ENTITY"))throw new IOException("设备 XML 包含不支持的外部定义");DocumentBuilderFactory f=DocumentBuilderFactory.newInstance();f.setNamespaceAware(true);f.setExpandEntityReferences(false);try{f.setFeature("http://apache.org/xml/features/disallow-doctype-decl",true);}catch(ParserConfigurationException ignored){}try{f.setFeature("http://xml.org/sax/features/external-general-entities",false);f.setFeature("http://xml.org/sax/features/external-parameter-entities",false);}catch(ParserConfigurationException ignored){}DocumentBuilder b=f.newDocumentBuilder();b.setEntityResolver((publicId,systemId)->new InputSource(new StringReader("")));return b.parse(new InputSource(new StringReader(raw)));}
 static String text(Node parent,String name){for(Node n=parent.getFirstChild();n!=null;n=n.getNextSibling())if(n.getNodeType()==Node.ELEMENT_NODE&&(name.equals(n.getLocalName())||name.equals(n.getNodeName())))return n.getTextContent().trim();return "";}
 static String first(Document doc,String name){NodeList nodes=doc.getElementsByTagNameNS("*",name);return nodes.getLength()==0?"":nodes.item(0).getTextContent().trim();}
 static Device descriptor(URL location,String body)throws Exception{Document doc=xml(body);String baseText=first(doc,"URLBase");URL base=baseText.isEmpty()?location:localUrl(new URL(location,baseText).toString());InetAddress origin=InetAddress.getByName(location.getHost());if(!origin.equals(InetAddress.getByName(base.getHost())))throw new IOException("设备基址与响应地址不一致");NodeList services=doc.getElementsByTagNameNS("*","service");for(int i=0;i<services.getLength();i++){Node service=services.item(i);String kind=text(service,"serviceType");if(!kind.matches("urn:schemas-upnp-org:service:AVTransport:[1-9][0-9]*"))continue;String path=text(service,"controlURL");if(path.isEmpty())continue;URL control=localUrl(new URL(base,path).toString());if(!origin.equals(InetAddress.getByName(control.getHost())))throw new IOException("设备控制地址与响应地址不一致");Node owner=service;while(owner!=null&&!"device".equals(owner.getLocalName())&&!"device".equals(owner.getNodeName()))owner=owner.getParentNode();String name=owner==null?"":text(owner,"friendlyName"),udn=owner==null?"":text(owner,"UDN");return new Device(name.isEmpty()?location.getHost():name,udn,kind,control);}throw new IOException("设备没有 AVTransport 视频播放服务");}
 static String read(InputStream in,int limit)throws Exception{if(in==null)return "";try(InputStream stream=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=stream.read(b))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("请求已取消");if(out.size()+n>limit)throw new IOException("设备响应过大");out.write(b,0,n);}return out.toString("UTF-8");}}
 static final class Scan implements AutoCloseable {
  volatile boolean cancelled;volatile String descriptorFailure="";volatile DatagramSocket socket;final Set<HttpURLConnection> requests=Collections.synchronizedSet(new HashSet<>());volatile ExecutorService pool;
  List<Device> find(InetAddress localAddress,int budgetMs)throws Exception{return find(localAddress,new InetSocketAddress("239.255.255.250",1900),budgetMs);}
  List<Device> find(InetAddress localAddress,InetSocketAddress target,int budgetMs)throws Exception{
   if(cancelled)throw new InterruptedIOException("搜索已取消");LinkedHashMap<String,URL> locations=new LinkedHashMap<>();MulticastSocket udp=new MulticastSocket(null);socket=udp;
   try{udp.setReuseAddress(true);udp.bind(new InetSocketAddress(localAddress,0));udp.setTimeToLive(2);if(localAddress!=null&&!localAddress.isLoopbackAddress())udp.setInterface(localAddress);udp.setSoTimeout(220);
    for(String st:new String[]{"urn:schemas-upnp-org:device:MediaRenderer:1",SERVICE}){byte[] request=("M-SEARCH * HTTP/1.1\r\nHOST: 239.255.255.250:1900\r\nMAN: \"ssdp:discover\"\r\nMX: 1\r\nST: "+st+"\r\n\r\n").getBytes(StandardCharsets.US_ASCII);udp.send(new DatagramPacket(request,request.length,target));}
    long end=System.nanoTime()+TimeUnit.MILLISECONDS.toNanos(budgetMs);byte[] bytes=new byte[8192];while(!cancelled&&System.nanoTime()<end){DatagramPacket packet=new DatagramPacket(bytes,bytes.length);try{udp.receive(packet);}catch(SocketTimeoutException e){continue;}Map<String,String> h=headers(new String(bytes,packet.getOffset(),packet.getLength(),StandardCharsets.UTF_8));String raw=h.get("location");if(raw==null||locations.size()>=24)continue;try{URL url=localUrl(raw);if(InetAddress.getByName(url.getHost()).equals(packet.getAddress()))locations.putIfAbsent(url.toString(),url);}catch(Exception ignored){}}
   }finally{udp.close();socket=null;}
   if(cancelled)throw new InterruptedIOException("搜索已取消");pool=Executors.newFixedThreadPool(4);CompletionService<Device> done=new ExecutorCompletionService<>(pool);ArrayList<Future<Device>> pending=new ArrayList<>();for(URL location:locations.values())pending.add(done.submit(()->fetch(location)));LinkedHashMap<String,Device> result=new LinkedHashMap<>();long until=System.nanoTime()+TimeUnit.SECONDS.toNanos(4);
   try{for(int i=0;i<pending.size()&&!cancelled;i++){long left=until-System.nanoTime();if(left<=0)break;Future<Device> future=done.poll(left,TimeUnit.NANOSECONDS);if(future==null)break;try{Device d=future.get();result.putIfAbsent(d.key(),d);}catch(ExecutionException error){Throwable cause=error.getCause();descriptorFailure=cause==null?"设备资料读取失败":String.valueOf(cause.getMessage()).replaceAll("https?://[^\\s]+","[设备地址]");}}}finally{for(Future<?> f:pending)f.cancel(true);pool.shutdownNow();synchronized(requests){for(HttpURLConnection c:requests)c.disconnect();requests.clear();}}
   if(cancelled)throw new InterruptedIOException("搜索已取消");if(result.isEmpty()&&!locations.isEmpty())throw new IOException("发现设备响应，但未取得可用的 DLNA 播放服务 · "+descriptorFailure);return new ArrayList<>(result.values());
  }
  Device fetch(URL location)throws Exception{if(cancelled||Thread.currentThread().isInterrupted())throw new InterruptedIOException("搜索已取消");HttpURLConnection c=(HttpURLConnection)location.openConnection();requests.add(c);c.setConnectTimeout(1800);c.setReadTimeout(2200);c.setInstanceFollowRedirects(false);try{if(c.getResponseCode()!=200)throw new IOException("设备资料读取失败");return descriptor(location,read(c.getInputStream(),512*1024));}finally{requests.remove(c);c.disconnect();}}
  public void close(){cancelled=true;DatagramSocket s=socket;if(s!=null)s.close();ExecutorService e=pool;if(e!=null)e.shutdownNow();synchronized(requests){for(HttpURLConnection c:requests)c.disconnect();requests.clear();}}
 }
 static String escape(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&apos;");}
 static String didl(String url,String title){return "<DIDL-Lite xmlns=\"urn:schemas-upnp-org:metadata-1-0/DIDL-Lite/\" xmlns:dc=\"http://purl.org/dc/elements/1.1/\" xmlns:upnp=\"urn:schemas-upnp-org:metadata-1-0/upnp/\"><item id=\"0\" parentID=\"-1\" restricted=\"1\"><dc:title>"+escape(title)+"</dc:title><upnp:class>object.item.videoItem</upnp:class><res protocolInfo=\"http-get:*:"+escape(CastRules.mime(url))+":*\">"+escape(url)+"</res></item></DIDL-Lite>";}
 static String envelope(Device device,String action,Map<String,String> arguments){StringBuilder body=new StringBuilder("<?xml version=\"1.0\" encoding=\"utf-8\"?><s:Envelope xmlns:s=\"http://schemas.xmlsoap.org/soap/envelope/\" s:encodingStyle=\"http://schemas.xmlsoap.org/soap/encoding/\"><s:Body><u:").append(action).append(" xmlns:u=\"").append(escape(device.service)).append("\">");for(Map.Entry<String,String> e:arguments.entrySet())body.append('<').append(e.getKey()).append('>').append(escape(e.getValue())).append("</").append(e.getKey()).append('>');return body.append("</u:").append(action).append("></s:Body></s:Envelope>").toString();}
 static Map<String,String> arguments(String... pairs){LinkedHashMap<String,String> map=new LinkedHashMap<>();map.put("InstanceID","0");for(int i=0;i<pairs.length;i+=2)map.put(pairs[i],pairs[i+1]);return map;}
 static Document action(Device device,String action,Map<String,String> arguments)throws Exception{
  localUrl(device.control.toString());HttpURLConnection c=(HttpURLConnection)device.control.openConnection();c.setConnectTimeout(3000);c.setReadTimeout(5000);c.setInstanceFollowRedirects(false);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","text/xml; charset=\"utf-8\"");c.setRequestProperty("SOAPAction","\""+device.service+"#"+action+"\"");byte[] request=envelope(device,action,arguments).getBytes(StandardCharsets.UTF_8);c.setFixedLengthStreamingMode(request.length);
  ScheduledFuture<?> kill=StremioStreams.WATCHDOG.schedule(c::disconnect,8,TimeUnit.SECONDS);
  try{try(OutputStream out=c.getOutputStream()){out.write(request);}int code=c.getResponseCode();String response=read(code>=400?c.getErrorStream():c.getInputStream(),256*1024);Document doc=response.isEmpty()?null:xml(response);if(doc!=null&&doc.getElementsByTagNameNS("*","Fault").getLength()>0){String message=first(doc,"errorDescription"),error=first(doc,"errorCode");throw new IOException("电视拒绝指令"+(error.isEmpty()?"":" ("+error+")")+(message.isEmpty()?"":"："+message));}if(code!=200)throw new IOException("电视返回 HTTP "+code);if(doc==null||doc.getElementsByTagNameNS("*",action+"Response").getLength()==0)throw new IOException("电视没有返回有效的 "+action+" 应答");return doc;}finally{kill.cancel(false);c.disconnect();}
 }
 static void play(Device device,String url,String title)throws Exception{String problem=CastRules.problem(new org.json.JSONObject().put("url",url));if(!problem.isEmpty())throw new IOException(problem);action(device,"SetAVTransportURI",arguments("CurrentURI",url,"CurrentURIMetaData",didl(url,title)));action(device,"Play",arguments("Speed","1"));}
 static void control(Device device,String command)throws Exception{if(!Arrays.asList("Play","Pause","Stop").contains(command))throw new IllegalArgumentException("不支持的播放控制");action(device,command,command.equals("Play")?arguments("Speed","1"):arguments());}
 static String state(Device device)throws Exception{return first(action(device,"GetTransportInfo",arguments()),"CurrentTransportState");}
}
